{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C27"],
      "claim": "Testosterone undecanoate, a long-chain fatty acid ester prodrug structurally analogous to the query's dodecyl ester motif, showed an absolute oral bioavailability of only 6.83 ± 3.32% in young women.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C58"],
      "claim": "Dimethandrolone undecanoate, another long-chain undecanoate ester prodrug, showed poor and inconsistent oral bioavailability in men.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Tetrabenazine had very low mean oral systemic availability (0.049 ± 0.032) in patients, supporting low F for a lipophilic, first-pass susceptible oral drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Felodipine, a lipophilic ester-containing drug, had an absolute oral bioavailability of 15.3% in fasted volunteers, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Tegaserod had an absolute oral bioavailability of approximately 10% in healthy volunteers, well below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C51"],
      "claim": "Batimastat, a peptide-like lipophilic drug, showed poor oral bioavailability in humans, consistent with low systemic exposure for this type of ester/amide-containing molecule.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "One nitrendipine report claimed 40% oral bioavailability in normal subjects, but this is an isolated outlier contradicted by multiple other nitrendipine studies and is not mechanistically transferable to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is orlistat, a minimally absorbed GI lipase inhibitor; the most transferable evidence from long-chain ester prodrugs (testosterone undecanoate, dimethandrolone undecanoate) and other lipophilic oral drugs consistently shows absolute oral bioavailability below 20%, supporting a low prediction.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for orlistat is present in the provided records.",
    "Most records are from unrelated chemical classes, limiting structural transferability.",
    "Isolated high-F outliers (e.g., nitrendipine 40%) are formulation- or method-specific and not representative of the query's expected behavior."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

